--
-- Struktur des Views `v_bucket_locus_trench`
--
DROP TABLE IF EXISTS `v_bucket_locus_trench`;

CREATE ALGORITHM=UNDEFINED DEFINER=`berenike`@`localhost` SQL SECURITY DEFINER VIEW `v_bucket_locus_trench`  AS  select `b`.`id` AS `bucket_id`,`b`.`number` AS `bucket_number`,`l`.`id` AS `locus_id`,`l`.`number` AS `locus_number`,`e`.`id` AS `excavation_id`,`e`.`number` AS `trench_number` from ((`bucket` `b` left join `locus` `l` on(`b`.`locus_id` = `l`.`id`)) left join `excavation` `e` on(`l`.`excavation_id` = `e`.`id`)) order by `b`.`number`,`l`.`number`,`e`.`number` limit 1000 ;

